    [228] = {code = "CoP 2-3", s = {["|1"] = "Check the Sewer entrance in Tavnazian Safehold to enter Phomiuna Aqueducts.", ["|10"] = "In this hallway, there are several torches on the wall.", ["|11"] = "Look at which Vana'diel day of the week it is (i.e. Firesday, Iceday) and find the oil lamps that correspond to the current day and the one", ["|12"] = "(The above list should be read like this ex: Firesday = Press Fire & Ice lamps on the wall)", ["|13"] = "Examine the two corresponding oil lamps within a short period to open the door to the west.", ["|14"] = "Head through it and make your way to the second Ornate Gate for a cutscene.", ["|15"] = "After both objectives are completed, exit the aqueducts and speak with Justinius at (J-6) on the top floor of Tavnazian Safehold (Home", ["|3"] = "Sneak and Invisible up and make your way toward (J-2) on the second map where the Minotaur is.", ["|4"] = "After you defeat the Minotaur, there is no cutscene.", ["|5"] = "Find the Iron Gate at (G-8) on the second map.", ["|7"] = "After you pass through the Iron Gate, find the Wooden Ladder at (E-8) for a cutscene.", ["|8"] = "Head left through the north door and proceed down the hallway into the first room you see.", ["|9"] = "Look for a ??? on a bookshelf in the southwest corner of the room."}},
