    [248] = {code = "CoP 2-5", s = {["|1"] = "After your group is prepared and geared up, head to the Dilapidated Gate at (F-7) of Misareaux Coast.", ["|2"] = "Check the Spatial Displacement ahead for a cutscene and to be transported to Riverne - Site #A01.", ["|3"] = "Head west to the Spatial Displacement and then northwest to another.", ["|4"] = "After you have your scales, make you way west to the Unstable Displacement at (G-10).", ["|5"] = "Head west again to the Unstable Displacement at (E-10) and use your other Giant Scale in the same manner above.", ["|6"] = "Head straight north and pass through the northeastern displacement into Monarch Linn.", ["|7"] = "You will now prepare for an instanced fight."}},
    [258] = {code = "CoP 3-1", s = {["|1"] = "After the Mammett fight you will appear in South Gustaberg near the Lighthouse.", ["|2"] = "Make your way to the Airship dock in Port Bastok.", ["|3"] = "Go to the second floor of the Metalworks and talk to Cid (H-8) for a cutscene."}},
    [318] = {code = "CoP 3-2", s = {["|1"] = "Enter Neptune's Spire in Lower Jeuno (F-7) and click on the door to the Tenshodo headquarters for a cutscene.", ["|2"] = "Go to Ru'Lude Gardens (H-7) and head toward the Audience Chamber of the palace."}},
    [325] = {code = "CoP 3-3", s = {["|1"] = "Zone into Northern San d'Oria for a cutscene.", ["|10"] = "Speak with Yoran-Oran at (E-5) in Windurst Walls (Home Point #1).", ["|11"] = "Speak with Kyume-Romeh at (F-10) in Windurst Waters.", ["|12"] = "Head to Windurst Waters (South Map Home Point #3) and speak with Honoi-Gomoi at (E-7).", ["|13"] = "Head back to Windurst Walls (Home Point #1) and speak with Yoran-Oran (E-5) again.", ["|14"] = "Travel to (K-8) in Attohwa Chasm and look for a spot marked as \"Loose Sand\".", ["|15"] = "To reach the Loose Sand you'll have to walk around the perimeter of Parradamo Tor: Start north, proceed north-east, then south until you", ["|16"] = "Clicking the Loose Sand spawns a level 51 NM Antlion named Lioumere.", ["|17"] = "Read the following four points after defeating the NM, but before clicking on the Loose Sand a second time:", ["|18"] = "You will receive a Mimeo Jewel after clicking the Loose Sand targetable location.", ["|19"] = "You will have exactly 30 Earth minutes to climb to the top of Parradamo Tor and reach the Cradle of Rebirth before the Mimeo Jewel breaks.", ["|2"] = "Head to the Cathedral and speak with Arnau at the altar (M-6).", ["|20"] = "The Jewel will also IMMEDIATELY BREAK upon using a Mount, zoning, disconnecting, or using a Nexus Cape while in same area, as it counts as", ["|21"] = "If the Jewel breaks, you will need to return to the Loose Sand and obtain another Mimeo Jewel.", ["|23"] = "After reading the points above, stand directly on top of the Loose Sand to obtain your Mimeo Jewel.", ["|24"] = "Make your way up Parradamo Tor.", ["|25"] = "To reach the base of the mountain at (K-9), turn around from the Loose Sand and proceed south-east to then hug the right wall while", ["|26"] = "Once you reach the top with your Jewel (and sanity!) intact, check the Cradle of Rebirth to obtain 3 Key Items: Mimeo Feather, Second Mimeo", ["|27"] = "Before leaving, if you have started the quest Middle Lands Investigation (part of a questline that unlocks Proto-Waypoints), go northwest", ["|29"] = "Return to Yoran-Oran at (E-5) in Windurst Walls (Home Point #1) once again.", ["|3"] = "Speak with Chasalvige, who is in the Cathedral's Manuscript room (L-6) for a cutscene.", ["|30"] = "Speak with Yujuju at (M-6) in Port Windurst (Home Point #3, near the Air Travel Agency)", ["|31"] = "Head inside the eastern half of the Optistery in Windurst Waters (North map, Home Point #1) to speak with Tosuka-Porika at (G-8).", ["|32"] = "Head back and talk to Yoran-Oran at (E-5) in Windurst Walls (Home Point #1) one final time to complete the Windurst path.", ["|34"] = "Head to the Metalworks (Home Point #1) and talk to Cid to complete the mission.", ["|4"] = "Head to Carpenters' Landing via the (E-6) entrance in Jugner Forest.", ["|5"] = "Speak with Guilloud at (H-10) to spawn the NM Overgrown Ivy.", ["|6"] = "Speak with Guilloud again after defeating Overgrown Ivy.", ["|7"] = "Speak with Hinaree at (B-6) in Southern San d'Oria upstairs in the Count's Manor for a cutscene to complete the San d'Oria path.", ["|8"] = "Zone into Windurst Waters for a cutscene.", ["|9"] = "Speak to Ohbiru-Dohbiru at (J-9) inside the Rhinostery, located in South Windurst Waters (Map 2), Home Point #3 will take you right next to"}},
    [350] = {code = "CoP 3-4", s = {["|1"] = "Zone into Lower Jeuno for a cutscene", ["|2"] = "Enter Neptune's Spire and click on the door to Tenshodo headquarters for another cutscene."}},
    [358] = {code = "CoP 3-5", s = {["|1"] = "Speak with Monberaux in Upper Jeuno at the Infirmary (G-10).", ["|10"] = "After Diabolos is defeated, return to Monberaux in Upper Jeuno to complete the mission.", ["|2"] = "Speak to Ghebi Damomohe inside Neptune's Spire of Lower Jeuno.", ["|3"] = "Everyone in your party (or if solo, you) must obtain a Pso'Xja pass.", ["|4"] = "After receiving your pass, the fastest path forward is a Survival Guide.", ["|5"] = "After entering, proceed on the singular path ahead to the central room at (H-8) to run through colored walls.", ["|6"] = "Pass through the walls at (H-7) and (I-7) in the following order:", ["|7"] = "After the last wall, take the elevator that appears at (H-8) to the bottom, and follow the northwestern path to the Stone Gate which leads", ["|8"] = "Rest and go over strategies in this area.", ["|9"] = "After Diabolos is defeated, return to Monberaux in Upper Jeuno to complete the mission."}},
    [368] = {code = "CoP 4-1", s = {["|2"] = "Zone into Tavnazian Safehold Home Point #3 for a cutscene and the beginning of Chapter 4.", ["|3"] = "Go south and speak with Despachiaire at (K-10) on the top floor (behind the Walnut Door) to begin the Mission.", ["|4"] = "Check the Dilapidated Gate at the south-west corner of (I-11) in Misareaux Coast."}},
