    [428] = {code = "CoP 4-3", s = {["|13"] = "After entering, take a right at the fork in the path, proceeding to the Wooden Gate at (G-8) for a cutscene.", ["|15"] = "After it is defeated, everyone on the missions needs to check the ??? to receive the Reliquiarium key.", ["|17"] = "Once past the doors, return to the same Wooden Gate again for a cutscene to end the mission.", ["|4"] = "Examine the Walnut Door at (K-7) just up the ramp from Justinius for a cutscene."}},
