    [448] = {code = "CoP 5-1", s = {["|1"] = "(Optional): Speak to Despachiaire through the Walnut Door at (K-10) on the top floor of Tavnazian Safehold for a cutscene.", ["|10"] = "Check the stone door again once Nunyunuwi is defeated to continue on.", ["|11"] = "In the next room, take the elevator down to the bottom (there are no Diremites at the bottom of this elevator ride).", ["|12"] = "Follow the path here until you reach another Stone Door for you to check, a cutscene will play and you will enter Promyvion - Vahzl.", ["|13"] = "You will get another cutscene upon entering.", ["|3"] = "(Optional): Speak to Chasalvige in Northern San d'Oria (L-6, Cathedral Manuscript Room) for a cutscene.", ["|4"] = "(Optional): Head to Port San d'Oria and speak to Anoki (H-6, Air Travel Agency) for a cutscene.", ["|5"] = "(Optional): Speak to Anoki a second time for your hint on where to go next.", ["|6"] = "Zone into Port Bastok for a cutscene.", ["|7"] = "Speak with Cid in the Metalworks for a cutscene.", ["|8"] = "Travel to the Nue Tower at (F-7) in Beaucedine Glacier, and enter the uncapped area of Pso'Xja for a small cutscene.", ["|9"] = "Move ahead until you reach the Stone Door at (H-8)."}},
    [518] = {code = "CoP 5-2", s = {["|5"] = "Zone into the uncapped area Spire of Vahzl at (F-8).", ["|6"] = "Use this time to rest and go over strategies.", ["|7"] = "After defeating the bosses, you'll be returned to Beaucedine Glacier.", ["|9"] = "Return to the Metalworks and speak with Cid."}},
    [530] = {code = "CoP 5-3", s = {["Past Sins|10"] = "After clearing the BC, speak with Cid in the Metalworks.", ["Past Sins|11"] = "Head to Newton Movalpolos and farm a Gold Key for everyone in your party.", ["Past Sins|12"] = "Head to Mine Shaft #2716 (see above for methods of getting there) and trade the Gold Key to the shaft entrance to get a cutscene.", ["Past Sins|13"] = "Return to Cid once again to finish this path.", ["Past Sins|2"] = "Talk to Despachiaire at the Tavnazian Safehold Home Point #3 - Top Floor (K-10).", ["Past Sins|3"] = "Speak with Perih Vashai at (K-7) in Windurst Woods Home Point #1.", ["Past Sins|4"] = "Travel to (H-11) on Purgonorgo Isle in Bibiki Bay and speak with the ???", ["Past Sins|5"] = "(Optional): Head to (E-5) in Windurst Walls and speak with Yoran-Oran for additional dialogue.", ["Past Sins|6"] = "Travel to Oldton Movalpolos and zone in for a cutscene.", ["Past Sins|7"] = "The next step is the BC at Mine Shaft #2716 and there are several options to get to the BC entrance.", ["Past Sins|8"] = "Before the battle is commenced, make sure to zone out into Newton Movalpolos and attune to the Home Point just outside after being", ["Past Sins|9"] = "After you have made your way to Mine Shaft #2716 rest up and go over strategies.", ["The Pursuit of Paradise|10"] = "Enter Batallia Downs from Upper Jeuno.", ["The Pursuit of Paradise|11"] = "Check the ??? again to obtain a Delkfutt recognition device.", ["The Pursuit of Paradise|12"] = "Head to the entrance of Lower Delkfutt's Tower.", ["The Pursuit of Paradise|13"] = "Go to (H-5) on the first floor of Lower Delkfutt's Tower and check the Cermet Door to spawn a Disaster Idol.", ["The Pursuit of Paradise|14"] = "After you defeat the Disaster Idol, check the Cermet Door once again for a cutscene.", ["The Pursuit of Paradise|15"] = "Head to the tower at (H-10) in Beaucedine Glacier and enter Pso'Xja for a cutscene.", ["The Pursuit of Paradise|16"] = "There are a few one way walls in here tha