    [560] = {s = {["|10"] = "Head to (J-9) of Uleguerand Range, jump into a hole on the ground and enter Bearclaw Pinnacle near Home Point #2.", ["|15"] = "After you defeat the Snoll Tzar, return to Bastok and speak to Cid in the Metalworks again to finish this path.", ["|2"] = "Head to Southern San d'Oria (A-6) (Home Point #4) and speak with Hinaree on the second floor of the manor for a short cutscene.", ["|3"] = "Zone into Port San d'Oria for a cutscene.", ["|4"] = "Speak with Chasalvige (L-6) in the Cathedral's Manuscript Room in Northern San d'Oria, left of the entrance.", ["|5"] = "Travel to Windurst Waters (J-8) (Home Point #3) and speak with Kerutoto in the North wing of the Rhinostery.", ["|7"] = "Go to Windurst Walls (E-5) (Home Point #1) and speak with Yoran-Oran.", ["|8"] = "Head to Attohwa Chasm (H-6), enter Boneyard Gully, and prepare for a boss fight.", ["|9"] = "After your party is geared up and ready, click on the Dark Miasma and enter the battlefield \"Head Wind\"."}},
    [578] = {code = "CoP 6-1", s = {["|1"] = "Speak with Pherimociel at (G-6) in Ru'Lude Gardens for a cutscene.", ["|2"] = "Head to the Marble Bridge (F-7) in Upper Jeuno and check the door for another cutscene.", ["|3"] = "Finally, zone back into Ru'Lude Gardens for another cutscene."}},
    [618] = {code = "CoP 6-2", s = {["|1"] = "Head toward the Palace in Ru'Lude Gardens for a cutscene.", ["|2"] = "Talk to Pherimociel at (G-6).", ["|3"] = "Travel to (I-11) in Misareaux Coast and check the Dilapidated Gate to spawn 3 Detector-type NMs.", ["|4"] = "Checking the Dilapidated Gate will spawn Warder Thalia, Warder Aglaia, and Warder Euphrosyne.", ["|5"] = "After you defeat the Warders, check the Dilapidated Gate again for a cutscene."}},
    [628] = {code = "CoP 6-3", s = {["|1"] = "Speak with Pherimociel at (G-6) in Ru'Lude Gardens for a cutscene (Home Point #1).", ["|2"] = "Head up the stairs and examine the Audience Chamber for another cutscene.", ["|3"] = "Travel to (H-9) in Selbina and speak with Mathilde in the Weaver's Guild office to complete the Mission."}},
    [638] = {code = "CoP 6-4", s = {["|1"] = "Go to the Metalworks and speak with Cid for a cutscene.", ["|10"] = "After you defeat each stage, you will be transported back to the Airship deck and your MP and HP will be recharged.", ["|11"] = "After you defeat Ultima, the last boss, you will appear in Lufaise Meadows at the Dilapidated Gate near Tavnazian Safehold.", ["|2"] = "Make your way to Sealion's Den.", ["|3"] = "Click the Iron Gate to get another cutscene", ["|4"] = "You will then be aboard the airship", ["|5"] = "Click the door on the airship to get a third cutscene and to begin the first fight.", ["|6"] = "The time limit in the battle is 45 minutes and it is very likely that you will want all that time.", ["|7"] = "After you have discussed your strategies and everyone has watched the cutscenes, click on the Iron Gate and enter the battlefield \"One to", ["|8"] = "You will appear on the deck of an airship.", ["|9"] = "This is a three stage fight, starting with 5 Mammets similar to the ones you've fought before."}},
    [648] = {code = "CoP 7-1", s = {["|1"] = "After the scene in Lufaise Meadows and receiving your Ducal Guard's Ring, head toward Tavnazian Safehold and zone in for a cutscene.", ["|2"] = "The following cutscenes can be done in any order:"}},
    [718] = {code = "CoP 7-2", s = {["|1"] = "Make your way toward the north Dilapidated Gate in Misareaux Coast (F-7) and check it for a cutscene.", ["|2"] = "Return to Sealion's Den and speak with Sueleen", ["|3"] = "Travel to Ru'Lude Gardens and head toward the Palace for a cutscene.", ["|4"] = "Travel to Upper Jeuno and check the door of the Marble Bridge Tavern for a final cutscene."}},
    [728] = {code = "CoP 7-3", s = {["|1"] = "Travel to Mine Shaft #2716 and check the Shaft Entrance for a cutscene.", ["|2"] = "Head to the Metalworks and speak with Cid."}},
    [738] = {code = "CoP 7-4", s = {["|1"] = "After your conversation with Cid, you will be off to fight 3 monsters all across the globe.", ["|10"] = "Talk to Sueleen in the Sealion's Den (H-6) (near Tavnazian Safehold Home Point #2) for a cutscene.", ["|2"] = "Travel to (E-7) in Misareaux Coast and check the Storage Compartment there to spawn a Bugard named Boggelmann.", ["|3"] = "Check the Storage Compartment again after it is defeated for a cutscene and obtain the Vessel of light.", ["|4"] = "Head to Carpenters' Landing from the east entrance in Jugner Forest (J-8).", ["|5"] = "Travel to (I-9) in Carpenters' Landing and look for a ??? near the water.", ["|6"] = "Check the ??? again once the Tonberries are dead to receive a cutscene.", ["|7"] = "Travel to (F-6) in Bibiki Bay and look for a ??? inside a cave.", ["|8"] = "Check the ??? after defeating Dalham for a cutscene.", ["|9"] = "After all of the monsters have been defeated, return to Cid to obtain Letters from Ulmia and Prishe."}},
    [748] = {code = "CoP 7-5", s = {["|1"] = "Travel to Sealion's Den and click the Iron Gate for a cutscene.", ["|2"] = "When your party is ready, click the Iron Gate and enter the battlefield \"The Warrior's Path\".", ["|3"] = "If ??? happens to connect all weapon skills during Meikyo Shisui, it will create a level 4 skillchain called Cosmic Elucidation dealing", ["|4"] = "After you beat ???, you will receive a cutscene and appear in Al'Taieu."}},
    [800] = {code = "CoP 8-1", s = {["|1"] = "Examine the Crystalline Field at (H-11) in Al'Taieu for a brief cutscene.", ["|2"] = "Examine the 3 Rubious Crystals to spawn trios of Ru'aern NMs.", ["|3"] = "Return to and examine the Crystalline Field to enter the Grand Palace of Hu'Xzoi.", ["|4"] = "Inside, examine the Gate of the Gods for a cutscene and your reward.", ["|5"] = "Then touch the east \"Particle Gate\" at (H-8) for another cutscene and to complete this mission.", ["|6"] = "In the Name of Science is now available, allowing Luminian organs to be exchanged for equipment."}},
    [818] = {code = "CoP 8-2", s = {["|1"] = "Examine the eastern Particle Gate at (H-8) in the Grand Palace of Hu'Xzoi for a cutscene that starts the Mission.", ["|10"] = "Map 2 (G-12) transporter.", ["|11"] = "Map 1 (G-10) escort (40 minute limit).", ["|12"] = "Map 1 (G-4) transporter.", ["|13"] = "Continue on to Map 2 (H-8) for the NM fight.", ["|14"] = "Enter the room and examine another Cermet Portal to spawn an Ix'ghrah.", ["|15"] = "Defeat it, then examine the Cermet Portal again for another cutscene.", ["|2"] = "The next section requires you to make your way through Hu'Xzoi by escorting the Quasilumin orb-looking NPCs that you might have noticed in", ["|3"] = "On your way through, you will run into Particle Gates that will not open.", ["|4"] = "You have to protect the Quasilumin while it travels to its destination.", ["|5"] = "On your way through it appears that the only enemies to pose a threat are the shapshifting Ix'ghrah and Eo'ghrah and the Eo'zdei which wait", ["|6"] = "Map 1 (Upper Level, M1) (J-8) escort (5 minute limit).", ["|7"] = "Map 1 (L-7) transporter.", ["|8"] = "Map 2 (Basement Level, M2) (L-8) escort (30 minute limit).", ["|9"] = "Map 2 (I-10) escort (30 minute limit)."}},
    [828] = {code = "CoP 8-3", s = {["|1"] = "First, check the Gate of the Gods (next to the Home Point) for a cutscene; otherwise, you will not have access to the upper floors (3-4).", ["|10"] = "Check the Particle Gate on the 3rd floor for a cutscene.", ["|11"] = "Check it again to enter the BC.", ["|12"] = "You begin the BC at the north end of the room, facing south at the pots.", ["|13"] = "The BC is against four Ix'zdei NMs.", ["|14"] = "Walk across the empty room and check the Luminous Convergence for a cutscene once you beat the pots.", ["|15"] = "After the fight and the following cutscene head south to the 'Particle Gate'.", ["|2"] = "You need to climb to the 4th floor of a specific Tower in The Garden of Ru'Hmet, which are located in the 5 points of the map.", ["|3"] = "Note: Once you're on the 4th floor of your Tower, check the Ebon Panel twice.", ["|4"] = "Go to the central area of The Garden of Ru'Hmet on the first floor.", ["|5"] = "There are four spinning Qn'zdei on each side of the elevator.", ["|6"] = "Once in the elevator room, step onto the platform and choose to ascend.", ["|7"] = "You must navigate this floor to collect both brands, Twilight and Dawn (Map 2).", ["|8"] = "If you want to save time, warp out and use the Home Point to quickly return to the elevator after obtaining each key item.", ["|9"] = "Head back to the central elevator and choose to ascend until you reach the 3rd floor in The Garden of Ru'Hmet."}},
    [840] = {code = "CoP 8-4", s = {["|1"] = "Zone into The Garden of Ru'Hmet and pass through the Cermet Portal to get to the main Garden elevator.", ["|13"] = "Once you've completed the previous cutscenes, head to Ru'Lude Gardens and approach the Palace for a cutscene.", ["|14"] = "Head to Upper Jeuno and click on the Door: Marble Bridge for a cutscene.", ["|15"] = "Click on the Marble Bridge door again to choose one of the 3 rings: Rajas Ring, Sattva Ring, Tamas Ring.", ["|16"] = "Head to Tavnazian Safehold (Home Point #3) and check the Walnut Door (K-7).", ["|17"] = "Head to Lufaise Meadows and approach the Blueblade Fell (J-6) for the final cutscene.", ["|18"] = "After all cutscenes are over, you have option to start both of the quests Requiem of Sin and Storms of Fate.", ["|2"] = "Choose to descend to zone into Empyreal Paradox.", ["|3"] = "Check the Transcendental Radiance for a cutscene and then check it again to enter the \"Dawn\" Battleground.", ["|4"] = "See final cutscenes below to receive your ring after beating Promathia.", ["|5"] = "Prishe joins you for this fight.", ["|6"] = "Selh'teus joins you for this fight as well.", ["|7"] = "If the entire party is KO'd at any point during the fight, you will be immediately removed from the battlefield.", ["|8"] = "Promathia has low evasion and is immune to Stun.", ["|9"] = "Promathia has two forms."}},
    [850] = {code = "CoP 8-5"},
}
